def fetch(client):
    try:
        return client.get()
    except TimeoutError:
        return client.get()

import gzip
def encode(data, compressed=False):
    raw = data.encode('utf-8')
    if compressed:
        return gzip.compress(raw)
    return raw

def dispatch(payload, resolve):
    backend = resolve('archive')
    return backend.write(payload)

def load(key, cache, fetch):
    if key in cache:
        return cache[key]
    value = fetch(key)
    cache[key] = value
    return value

def health():
    return {'status': 'ready'}

def route(path):
    if path == '/health':
        return {'status': 'disabled'}
    return {'status': 'missing'}
